package com.grandsigil.client;

import java.util.ArrayList;
import java.util.List;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import org.joml.Vector3f;
import org.joml.Vector3fc;

public final class Bolt {
    private static final int MAX_ARCS = 900;
    private static final float BRANCH_CHANCE = 0.32f;
    private static final float BRANCH_REACH = 0.75f;
    private static final float BRANCH_WIDTH = 0.55f;
    private static final float BRANCH_ALPHA = 0.62f;
    private static final float CHAOS_DECAY = 0.58f;

    private Bolt() {
    }

    public static void generate(List<Arc> out, Vector3f from, Vector3f to, RandomSource random, int levels, float chaos, float width, float alpha, int branches) {
        Bolt.split(out, from, to, random, levels, chaos, width, alpha, branches);
    }

    private static void split(List<Arc> out, Vector3f a, Vector3f b, RandomSource random, int levels, float chaos, float width, float alpha, int branches) {
        if (out.size() >= 900) {
            return;
        }
        if (levels <= 0) {
            out.add(new Arc(new Vector3f((Vector3fc)a), new Vector3f((Vector3fc)b), width, alpha));
            return;
        }
        Vector3f run = new Vector3f((Vector3fc)b).sub((Vector3fc)a);
        float length = run.length();
        if (length < 1.0E-4f) {
            return;
        }
        Vector3f mid = new Vector3f((Vector3fc)a).add((Vector3fc)b).mul(0.5f);
        Vector3f sideways = Bolt.perpendicular(run, random);
        mid.add((Vector3fc)sideways.mul(length * chaos * (random.m_188501_() - 0.5f) * 2.0f));
        float next = chaos * 0.58f;
        Bolt.split(out, a, mid, random, levels - 1, next, width, alpha, branches);
        Bolt.split(out, mid, b, random, levels - 1, next, width, alpha, branches);
        if (branches > 0 && random.m_188501_() < 0.32f) {
            Vector3f heading = new Vector3f((Vector3fc)b).sub((Vector3fc)mid).normalize();
            heading.add((Vector3fc)Bolt.perpendicular(heading, random).mul(0.55f + random.m_188501_() * 0.8f));
            heading.normalize().mul(length * 0.75f * (0.45f + random.m_188501_() * 0.7f));
            Vector3f tip = new Vector3f((Vector3fc)mid).add((Vector3fc)heading);
            Bolt.split(out, mid, tip, random, levels - 1, chaos * 1.15f, width * 0.55f, alpha * 0.62f, branches - 1);
        }
    }

    private static Vector3f perpendicular(Vector3f run, RandomSource random) {
        Vector3f axis = Math.abs(run.y) > 0.9f * run.length() ? new Vector3f(1.0f, 0.0f, 0.0f) : new Vector3f(0.0f, 1.0f, 0.0f);
        Vector3f u = new Vector3f((Vector3fc)run).cross((Vector3fc)axis).normalize();
        Vector3f v = new Vector3f((Vector3fc)run).cross((Vector3fc)u).normalize();
        float angle = random.m_188501_() * ((float)Math.PI * 2);
        return u.mul(Mth.m_14089_((float)angle)).add((Vector3fc)v.mul(Mth.m_14031_((float)angle))).normalize();
    }

    public static void onSphere(List<Arc> out, Vector3f centre, float radius, Vector3f from, Vector3f to, RandomSource random, int levels, float chaos, float width, float alpha, int branches) {
        ArrayList<Arc> raw = new ArrayList<Arc>();
        Bolt.split(raw, from, to, random, levels, chaos, width, alpha, branches);
        for (Arc arc : raw) {
            out.add(new Arc(Bolt.project(arc.from(), centre, radius), Bolt.project(arc.to(), centre, radius), arc.width(), arc.alpha()));
        }
    }

    private static Vector3f project(Vector3f point, Vector3f centre, float radius) {
        Vector3f out = new Vector3f((Vector3fc)point).sub((Vector3fc)centre);
        float length = out.length();
        return length < 1.0E-4f ? new Vector3f((Vector3fc)centre) : out.mul(radius / length).add((Vector3fc)centre);
    }

    public record Arc(Vector3f from, Vector3f to, float width, float alpha) {
    }
}

